## Task
End-to-end UI tests for the complete onboarding flow including API key entry and validation.

## Testing Strategy
- Use XCUITest for full UI automation
- Test complete user journey from app launch to first use
- Verify all UI states and transitions
- Log every user action and screen state

## Test Coverage

### OnboardingFlowTests
```swift
import XCTest

final class OnboardingFlowTests: XCTestCase {
    var app: XCUIApplication!
    var logger: TestLogger!

    override func setUp() {
        super.setUp()
        continueAfterFailure = false

        app = XCUIApplication()
        app.launchArguments = ["--uitesting", "--reset-state"]
        logger = TestLogger(testName: name)

        logger.info("Launching app in fresh state")
        app.launch()
    }

    override func tearDown() {
        print(logger.summary())
        super.tearDown()
    }

    // MARK: - Welcome Screen Tests

    func testOnboarding_WelcomeScreen_DisplaysCorrectly() throws {
        logger.step(1, "Verifying welcome screen elements")

        // Check title
        let welcomeTitle = app.staticTexts["Welcome to BookQuotes"]
        XCTAssertTrue(welcomeTitle.waitForExistence(timeout: 5))
        logger.debug("Welcome title found")

        // Check app description
        XCTAssertTrue(app.staticTexts.matching(
            NSPredicate(format: "label CONTAINS 'capture quotes'")
        ).count > 0)
        logger.debug("App description found")

        // Check Get Started button
        let getStartedButton = app.buttons["Get Started"]
        XCTAssertTrue(getStartedButton.exists)
        XCTAssertTrue(getStartedButton.isEnabled)
        logger.debug("Get Started button enabled")

        logger.success("Welcome screen displays correctly")
    }

    func testOnboarding_TapGetStarted_NavigatesToAPIKeyEntry() throws {
        logger.step(1, "Tapping Get Started")
        app.buttons["Get Started"].tap()

        logger.step(2, "Verifying API key entry screen")
        let apiKeyField = app.textFields["Enter your Gemini API key"]
        XCTAssertTrue(apiKeyField.waitForExistence(timeout: 3))

        // Check for help link
        XCTAssertTrue(app.buttons["Get a free API key"].exists)

        logger.success("Navigated to API key entry")
    }

    // MARK: - API Key Entry Tests

    func testAPIKeyEntry_EmptySubmit_ShowsError() throws {
        logger.step(1, "Navigating to API key screen")
        app.buttons["Get Started"].tap()

        logger.step(2, "Tapping submit without entering key")
        app.buttons["Continue"].tap()

        logger.step(3, "Verifying error message")
        let errorText = app.staticTexts.matching(
            NSPredicate(format: "label CONTAINS 'API key is required'")
        )
        XCTAssertTrue(errorText.count > 0)

        logger.success("Empty submission shows error")
    }

    func testAPIKeyEntry_InvalidKey_ShowsValidationError() throws {
        logger.step(1, "Navigating to API key screen")
        app.buttons["Get Started"].tap()

        logger.step(2, "Entering invalid key")
        let apiKeyField = app.textFields.element(boundBy: 0)
        apiKeyField.tap()
        apiKeyField.typeText("invalid-key-123")

        logger.step(3, "Submitting")
        app.buttons["Continue"].tap()

        logger.step(4, "Waiting for validation")
        // Wait for API validation to complete
        let errorMessage = app.staticTexts.matching(
            NSPredicate(format: "label CONTAINS 'Invalid API key' OR label CONTAINS 'validation failed'")
        )
        XCTAssertTrue(errorMessage.firstMatch.waitForExistence(timeout: 10))

        logger.success("Invalid key shows validation error")
    }

    func testAPIKeyEntry_ValidKey_ProceedsToNextStep() throws {
        try XCTSkipUnless(
            !testAPIKey.isEmpty,
            "Valid test API key required"
        )

        logger.step(1, "Navigating to API key screen")
        app.buttons["Get Started"].tap()

        logger.step(2, "Entering valid key")
        let apiKeyField = app.textFields.element(boundBy: 0)
        apiKeyField.tap()
        apiKeyField.typeText(testAPIKey)

        logger.step(3, "Submitting")
        app.buttons["Continue"].tap()

        logger.step(4, "Verifying next screen")
        // Should see marking styles or camera permission screen
        let nextScreen = app.staticTexts.matching(
            NSPredicate(format: "label CONTAINS 'Marking' OR label CONTAINS 'Camera'")
        )
        XCTAssertTrue(nextScreen.firstMatch.waitForExistence(timeout: 10))

        logger.success("Valid key proceeds to next step")
    }

    // MARK: - Marking Style Selection Tests

    func testMarkingStyles_DefaultSelection_ShowsTemplates() throws {
        try skipToMarkingStyles()

        logger.step(1, "Verifying marking style options")

        // Check template options exist
        XCTAssertTrue(app.buttons["Standard"].exists)
        XCTAssertTrue(app.buttons["Academic"].exists)
        XCTAssertTrue(app.buttons["Business"].exists)

        logger.success("Marking style templates displayed")
    }

    func testMarkingStyles_SelectTemplate_ShowsPreview() throws {
        try skipToMarkingStyles()

        logger.step(1, "Selecting Academic template")
        app.buttons["Academic"].tap()

        logger.step(2, "Verifying preview shows academic markings")
        XCTAssertTrue(app.staticTexts["Primary Source"].waitForExistence(timeout: 2))
        XCTAssertTrue(app.staticTexts["Citation Needed"].exists)

        logger.success("Academic template preview shown")
    }

    // MARK: - Camera Permission Tests

    func testCameraPermission_PromptDisplayed() throws {
        try completeOnboardingUntilCamera()

        logger.step(1, "Verifying camera permission screen")

        XCTAssertTrue(app.staticTexts.matching(
            NSPredicate(format: "label CONTAINS 'Camera Access'")
        ).count > 0)

        XCTAssertTrue(app.buttons["Enable Camera"].exists)

        logger.success("Camera permission screen displayed")
    }

    // MARK: - Complete Flow Tests

    func testCompleteOnboarding_AllSteps_ReachesMainApp() throws {
        try XCTSkipUnless(!testAPIKey.isEmpty, "API key required")

        logger.step(1, "Starting onboarding")
        app.buttons["Get Started"].tap()

        logger.step(2, "Entering API key")
        let apiKeyField = app.textFields.element(boundBy: 0)
        apiKeyField.tap()
        apiKeyField.typeText(testAPIKey)
        app.buttons["Continue"].tap()

        // Wait for validation
        try await Task.sleep(for: .seconds(3))

        logger.step(3, "Selecting marking style")
        if app.buttons["Standard"].waitForExistence(timeout: 5) {
            app.buttons["Standard"].tap()
            app.buttons["Continue"].tap()
        }

        logger.step(4, "Handling camera permission")
        if app.buttons["Enable Camera"].waitForExistence(timeout: 5) {
            app.buttons["Enable Camera"].tap()
            // System dialog will appear - skip for now
            if app.buttons["Skip"].exists {
                app.buttons["Skip"].tap()
            }
        }

        logger.step(5, "Verifying main app reached")
        // Should see main tab bar
        let tabBar = app.tabBars.firstMatch
        XCTAssertTrue(tabBar.waitForExistence(timeout: 10))

        logger.success("Complete onboarding flow successful")
    }

    // MARK: - Helpers

    private var testAPIKey: String {
        ProcessInfo.processInfo.environment["GEMINI_TEST_API_KEY"] ?? ""
    }

    private func skipToMarkingStyles() throws {
        try XCTSkipUnless(!testAPIKey.isEmpty, "API key required")
        app.buttons["Get Started"].tap()
        let field = app.textFields.element(boundBy: 0)
        field.tap()
        field.typeText(testAPIKey)
        app.buttons["Continue"].tap()
        _ = app.buttons["Standard"].waitForExistence(timeout: 10)
    }

    private func completeOnboardingUntilCamera() throws {
        try skipToMarkingStyles()
        app.buttons["Standard"].tap()
        app.buttons["Continue"].tap()
        _ = app.buttons["Enable Camera"].waitForExistence(timeout: 5)
    }
}
