## Task
Create reusable test fixtures that generate real model instances with sensible defaults, supporting customization for specific test scenarios.

## Why This Matters
Tests need consistent, realistic data. Fixtures provide:
- **Reusable factories** for all model types
- **Sensible defaults** that represent real usage
- **Customizable** for edge cases
- **Real images** for visual testing

## Implementation Details

### TestFixtures
```swift
import Foundation
import SwiftData
import UIKit

/// Factory methods for creating real test data
/// All methods return actual model instances, not mocks
enum TestFixtures {

    // MARK: - Books

    struct BookBuilder {
        var title: String = "Atomic Habits"
        var author: String = "James Clear"
        var subtitle: String? = "An Easy & Proven Way to Build Good Habits"
        var isbn: String? = "978-0735211292"
        var status: Book.ReadingStatus = .reading
        var coverThumbnailData: Data? = nil

        func build() -> Book {
            let book = Book(title: title, author: author)
            book.subtitle = subtitle
            book.isbn = isbn
            book.status = status
            book.coverThumbnailData = coverThumbnailData ?? Self.defaultCoverImage
            return book
        }

        static let defaultCoverImage: Data = {
            // Generate a simple colored rectangle as cover placeholder
            let size = CGSize(width: 100, height: 150)
            let renderer = UIGraphicsImageRenderer(size: size)
            let image = renderer.image { ctx in
                UIColor.systemBlue.setFill()
                ctx.fill(CGRect(origin: .zero, size: size))
            }
            return image.jpegData(compressionQuality: 0.8) ?? Data()
        }()
    }

    static func book(_ configure: (inout BookBuilder) -> Void = { _ in }) -> Book {
        var builder = BookBuilder()
        configure(&builder)
        return builder.build()
    }

    /// Pre-configured book fixtures
    static var atomicHabits: Book { book() }

    static var deepWork: Book {
        book { b in
            b.title = "Deep Work"
            b.author = "Cal Newport"
            b.subtitle = "Rules for Focused Success in a Distracted World"
            b.status = .completed
        }
    }

    static var thinkingFastAndSlow: Book {
        book { b in
            b.title = "Thinking, Fast and Slow"
            b.author = "Daniel Kahneman"
            b.status = .wantToRead
        }
    }

    // MARK: - Quotes

    struct QuoteBuilder {
        var text: String = "Every action you take is a vote for the type of person you wish to become."
        var pageNumber: Int? = 38
        var marginNote: String? = nil
        var markingType: MarkingType = .underline
        var confidence: Double? = 0.95
        var isFavorite: Bool = false
        var book: Book? = nil

        func build() -> Quote {
            let quote = Quote(text: text)
            quote.pageNumber = pageNumber
            quote.marginNote = marginNote
            quote.markingType = markingType
            quote.confidence = confidence
            quote.isFavorite = isFavorite
            quote.book = book
            return quote
        }
    }

    static func quote(_ configure: (inout QuoteBuilder) -> Void = { _ in }) -> Quote {
        var builder = QuoteBuilder()
        configure(&builder)
        return builder.build()
    }

    /// Pre-configured quote fixtures
    static var voteQuote: Quote { quote() }

    static var habitsQuote: Quote {
        quote { q in
            q.text = "You do not rise to the level of your goals. You fall to the level of your systems."
            q.pageNumber = 27
            q.marginNote = "Key insight!"
            q.markingType = .doubleUnderline
        }
    }

    static var lowConfidenceQuote: Quote {
        quote { q in
            q.text = "Partially readable text here..."
            q.confidence = 0.45
            q.marginNote = "Hard to read"
        }
    }

    // MARK: - Marking Definitions

    static func markingDefinition(
        name: String = "Underline",
        visualDescription: String = "Single line under text",
        meaning: String = "Important passage",
        icon: String = "underline",
        colorName: String = "blue",
        isSystemDefault: Bool = true
    ) -> MarkingDefinition {
        let definition = MarkingDefinition(
            name: name,
            visualDescription: visualDescription,
            meaning: meaning,
            icon: icon,
            colorName: colorName
        )
        definition.isSystemDefault = isSystemDefault
        return definition
    }

    static var allSystemMarkings: [MarkingDefinition] {
        MarkingDefinition.systemDefaults
    }

    // MARK: - Search Test Data

    /// Generate a large dataset for performance testing
    static func largeBookCollection(bookCount: Int, quotesPerBook: Int) -> [Book] {
        let words = ["happiness", "success", "mindset", "growth", "learning",
                     "wisdom", "focus", "habits", "discipline", "motivation"]

        return (0..<bookCount).map { i in
            let book = Book(title: "Test Book \(i)", author: "Author \(i % 10)")

            for j in 0..<quotesPerBook {
                let randomWords = (0..<10).map { _ in words.randomElement()! }
                let quote = Quote(text: randomWords.joined(separator: " "))
                quote.pageNumber = j + 1
                quote.book = book
            }

            return book
        }
    }

    // MARK: - Images

    /// Real test images for capture testing
    enum TestImages {
        /// A simple book page with text
        static var bookPage: Data {
            generateBookPageImage()
        }

        /// A book cover image
        static var bookCover: Data {
            generateBookCoverImage()
        }

        /// A blurry/low quality image
        static var blurryPage: Data {
            generateBlurryImage()
        }

        private static func generateBookPageImage() -> Data {
            let size = CGSize(width: 400, height: 600)
            let renderer = UIGraphicsImageRenderer(size: size)
            let image = renderer.image { ctx in
                // White background
                UIColor.white.setFill()
                ctx.fill(CGRect(origin: .zero, size: size))

                // Draw some "text lines"
                UIColor.black.setFill()
                for i in 0..<20 {
                    let y = CGFloat(50 + i * 25)
                    ctx.fill(CGRect(x: 30, y: y, width: CGFloat.random(in: 200...350), height: 3))
                }

                // Draw an "underline" marking
                UIColor.yellow.withAlphaComponent(0.5).setFill()
                ctx.fill(CGRect(x: 30, y: 150, width: 300, height: 20))
            }
            return image.jpegData(compressionQuality: 0.9) ?? Data()
        }

        private static func generateBookCoverImage() -> Data {
            let size = CGSize(width: 300, height: 450)
            let renderer = UIGraphicsImageRenderer(size: size)
            let image = renderer.image { ctx in
                // Gradient background
                let colors = [UIColor.systemIndigo.cgColor, UIColor.systemPurple.cgColor]
                let gradient = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(),
                                         colors: colors as CFArray,
                                         locations: [0, 1])!
                ctx.cgContext.drawLinearGradient(gradient,
                                                  start: .zero,
                                                  end: CGPoint(x: 0, y: size.height),
                                                  options: [])

                // Title area
                UIColor.white.withAlphaComponent(0.9).setFill()
                ctx.fill(CGRect(x: 20, y: 150, width: 260, height: 30))
                ctx.fill(CGRect(x: 40, y: 200, width: 220, height: 15))
            }
            return image.jpegData(compressionQuality: 0.9) ?? Data()
        }

        private static func generateBlurryImage() -> Data {
            // Create a deliberately low-quality image
            let size = CGSize(width: 100, height: 150) // Small size = pixelated when scaled
            let renderer = UIGraphicsImageRenderer(size: size)
            let image = renderer.image { ctx in
                UIColor.gray.setFill()
                ctx.fill(CGRect(origin: .zero, size: size))
            }
            return image.jpegData(compressionQuality: 0.1) ?? Data() // Low quality
        }
    }
}
