## Task
Implement StoreKit 2 subscription handling with paywall and subscription management.

## Why This Matters
This is how users pay. StoreKit 2 is much simpler than the original StoreKit and handles most edge cases automatically.

## Implementation Details

### SubscriptionService
```swift
import StoreKit

@Observable
class SubscriptionService {
    private(set) var products: [Product] = []
    private(set) var purchasedSubscription: Product?
    private(set) var subscriptionStatus: Product.SubscriptionInfo.Status?

    private let productIds = ["com.bookquotes.monthly", "com.bookquotes.yearly"]

    func loadProducts() async throws {
        products = try await Product.products(for: productIds)
    }

    func purchase(_ product: Product) async throws -> Transaction? {
        let result = try await product.purchase()

        switch result {
        case .success(let verification):
            let transaction = try checkVerified(verification)
            await transaction.finish()
            await updateSubscriptionStatus()
            return transaction

        case .pending:
            return nil

        case .userCancelled:
            return nil

        @unknown default:
            return nil
        }
    }

    func updateSubscriptionStatus() async {
        for await result in Transaction.currentEntitlements {
            if case .verified(let transaction) = result {
                if transaction.productType == .autoRenewable {
                    purchasedSubscription = products.first { $0.id == transaction.productID }
                    // Sync with backend
                    await syncSubscriptionWithServer(transaction)
                }
            }
        }
    }

    func restorePurchases() async throws {
        try await AppStore.sync()
        await updateSubscriptionStatus()
    }
}
