## Task
Refactor GeminiService to call our proxy server instead of Gemini API directly.

## Why This Matters
With the subscription model, all API calls go through our proxy which handles authentication and billing. The app never sees the Gemini API key.

## Implementation Details

### Updated GeminiService
```swift
actor GeminiService {
    private let baseURL = "https://api.bookquotes.app"  // Your proxy
    private let authService: AuthService
    private let session: URLSession

    init(authService: AuthService) {
        self.authService = authService
        self.session = URLSession.shared
    }

    func extractBookMetadata(from imageData: Data) async throws -> BookMetadata {
        let request = try buildRequest(
            endpoint: "/api/extract-cover",
            imageData: imageData,
            prompt: Self.coverExtractionPrompt
        )

        let (data, response) = try await session.data(for: request)
        try handleResponseErrors(response)

        return try JSONDecoder().decode(BookMetadata.self, from: data)
    }

    func extractQuotes(from imageData: Data, markings: [MarkingDefinition]) async throws -> QuoteExtractionResult {
        let prompt = buildQuoteExtractionPrompt(markings: markings)

        let request = try buildRequest(
            endpoint: "/api/extract-quotes",
            imageData: imageData,
            prompt: prompt
        )

        let (data, response) = try await session.data(for: request)
        try handleResponseErrors(response)

        return try JSONDecoder().decode(QuoteExtractionResult.self, from: data)
    }

    private func buildRequest(endpoint: String, imageData: Data, prompt: String) throws -> URLRequest {
        guard let token = authService.sessionToken else {
            throw GeminiError.notAuthenticated
        }

        var request = URLRequest(url: URL(string: baseURL + endpoint)!)
        request.httpMethod = "POST"
        request.addValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        request.addValue("application/json", forHTTPHeaderField: "Content-Type")

        let body = GeminiRequest(
            imageBase64: imageData.base64EncodedString(),
            prompt: prompt
        )
        request.httpBody = try JSONEncoder().encode(body)

        return request
    }

    private func handleResponseErrors(_ response: URLResponse) throws {
        guard let http = response as? HTTPURLResponse else { return }

        switch http.statusCode {
        case 200...299: return
        case 401: throw GeminiError.notAuthenticated
        case 402: throw GeminiError.subscriptionRequired
        case 429: throw GeminiError.rateLimited
        default: throw GeminiError.serverError(http.statusCode)
        }
    }
}

enum GeminiError: Error {
    case notAuthenticated
    case subscriptionRequired
    case rateLimited
    case serverError(Int)
    case extractionFailed(String)
}
