### Did-You-Mean Service
```swift
extension SearchDatabase {
    /// Suggest correction for likely typos
    func didYouMean(_ query: String) async throws -> String? {
        let terms = query.lowercased().components(separatedBy: .whitespaces)
        var corrections: [String] = []

        for term in terms {
            // Check if term exists in our vocabulary
            let exists = try await termExists(term)

            if !exists && term.count >= 4 {
                // Find closest match using trigram similarity
                if let suggestion = try await closestTerm(to: term) {
                    corrections.append(suggestion)
                } else {
                    corrections.append(term)
                }
            } else {
                corrections.append(term)
            }
        }

        let corrected = corrections.joined(separator: " ")
        return corrected != query.lowercased() ? corrected : nil
    }

    /// Find closest matching term using trigram similarity
    private func closestTerm(to term: String) async throws -> String? {
        // Use FTS5 vocab table to find similar terms
        let sql = """
            SELECT term, 
                   (length(term) + length(?1) - 2 * (
                       SELECT count(*) FROM (
                           SELECT substr(?1, i, 3) as tri
                           FROM (SELECT 1 as i UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5)
                           WHERE i <= length(?1) - 2
                           INTERSECT
                           SELECT substr(term, i, 3)
                           FROM (SELECT 1 as i UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5)
                           WHERE i <= length(term) - 2
                       )
                   )) as distance
            FROM quotes_fts_vocab
            WHERE term LIKE ?2
            ORDER BY distance ASC
            LIMIT 1
        """

        let firstChar = String(term.prefix(1))
        return try await executeScalar(sql, params: [term, "\(firstChar)%"])
    }
}
