## Task
Implement a dedicated service and UI flow for camera permission handling. This is a **CRITICAL UX PINCH POINT** - users who hit a permission wall and don't understand how to fix it will uninstall.

## Why This Matters
Camera permission is the first barrier users encounter after onboarding. A poor permission flow = immediate uninstall. A good flow = builds trust and guides users to success.

## Implementation Details

### CameraPermissionService
```swift
@MainActor
@Observable
final class CameraPermissionService {
    enum PermissionStatus {
        case notDetermined
        case authorized
        case denied
        case restricted
    }

    private(set) var status: PermissionStatus = .notDetermined

    func checkStatus() {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .notDetermined: status = .notDetermined
        case .authorized: status = .authorized
        case .denied: status = .denied
        case .restricted: status = .restricted
        @unknown default: status = .denied
        }
    }

    func requestPermission() async -> Bool {
        let granted = await AVCaptureDevice.requestAccess(for: .video)
        status = granted ? .authorized : .denied
        return granted
    }

    func openSettings() {
        guard let url = URL(string: UIApplication.openSettingsURLString) else { return }
        UIApplication.shared.open(url)
    }
}
