### CaptureQueueManager
```swift
actor CaptureQueueManager {
    private let modelContext: ModelContext
    private let geminiService: GeminiService
    private let networkMonitor: NetworkMonitor

    private var isProcessing = false
    private let maxRetries = 3
    private let retryDelay: [TimeInterval] = [5, 30, 120]  // Exponential backoff

    @Published var queueStats: QueueStats

    struct QueueStats {
        var pendingCount: Int
        var processingCount: Int
        var failedCount: Int
        var isProcessing: Bool
    }

    func addToQueue(imageData: Data, book: Book) async throws -> CaptureQueueItem {
        // Save image to disk
        // Create queue item
        // Trigger processing if online
    }

    func startProcessing() async {
        guard !isProcessing, networkMonitor.isConnected else { return }
        isProcessing = true

        while let item = await fetchNextPendingItem() {
            await processItem(item)
        }

        isProcessing = false
    }

    private func processItem(_ item: CaptureQueueItem) async {
        item.status = .processing
        item.dateLastAttempt = Date()

        do {
            let result = try await geminiService.extractQuotes(from: loadImage(item))
            item.extractedQuotes = result.quotes
            item.status = .completed
            item.dateCompleted = Date()
        } catch {
            item.retryCount += 1
            if item.retryCount >= maxRetries {
                item.status = .failed
                item.lastError = error.localizedDescription
            } else {
                item.status = .pending
                // Schedule retry with backoff
            }
        }
    }

    func retryFailed(item: CaptureQueueItem) async {
        item.status = .pending
        item.retryCount = 0
        await startProcessing()
    }
}
