- **By book** - "Show only quotes from Atomic Habits"
- **By marking type** - "Show only my action items (asterisks)"
- **By date** - "Quotes from this month"
- **By favorites** - "Only my starred quotes"

## Implementation Details

### SearchFilters Model
```swift
struct SearchFilters: Equatable {
    var bookIds: Set<UUID> = []           // Empty = all books
    var markingTypes: Set<String> = []    // Empty = all types
    var dateRange: DateRange = .allTime
    var favoritesOnly: Bool = false
    var minConfidence: Double? = nil      // Filter low-confidence extractions

    enum DateRange: String, CaseIterable {
        case allTime = "All Time"
        case today = "Today"
        case thisWeek = "This Week"
        case thisMonth = "This Month"
        case thisYear = "This Year"
        case custom = "Custom"

        var dateInterval: DateInterval? {
            let calendar = Calendar.current
            let now = Date()

            switch self {
            case .allTime: return nil
            case .today: 
                return calendar.dateInterval(of: .day, for: now)
            case .thisWeek:
                return calendar.dateInterval(of: .weekOfYear, for: now)
            case .thisMonth:
                return calendar.dateInterval(of: .month, for: now)
            case .thisYear:
                return calendar.dateInterval(of: .year, for: now)
            case .custom:
                return nil // Handled separately
            }
        }
    }

    var isActive: Bool {
        \!bookIds.isEmpty || \!markingTypes.isEmpty || 
        dateRange \!= .allTime || favoritesOnly || minConfidence \!= nil
    }

    var activeFilterCount: Int {
        var count = 0
        if \!bookIds.isEmpty { count += 1 }
        if \!markingTypes.isEmpty { count += 1 }
        if dateRange \!= .allTime { count += 1 }
        if favoritesOnly { count += 1 }
        if minConfidence \!= nil { count += 1 }
        return count
    }
}
```

### FTS5 Query with Filters
```swift
extension SearchDatabase {
    func search(
        query: String, 
        scope: SearchScope,
        filters: SearchFilters
    ) async throws -> SearchResults {
        var sql = """
            SELECT 
                q.quote_id,
                q.book_id,
                snippet(quotes_fts, 2, '<mark>', '</mark>', '...', 32) as snippet,
                bm25(quotes_fts) as rank
            FROM quotes_fts q
            WHERE quotes_fts MATCH ?
        """

        var params: [Any] = [buildFTSQuery(query)]

        // Add filters
        if \!filters.bookIds.isEmpty {
            let placeholders = filters.bookIds.map { _ in "?" }.joined(separator: ",")
            sql += " AND q.book_id IN (\(placeholders))"
            params.append(contentsOf: filters.bookIds.map { $0.uuidString })
        }

        if let dateInterval = filters.dateRange.dateInterval {
            sql += " AND q.date_added BETWEEN ? AND ?"
            params.append(dateInterval.start.timeIntervalSince1970)
            params.append(dateInterval.end.timeIntervalSince1970)
        }

        // Note: marking_type and favorites filters applied in Swift 
        // after fetching (FTS5 can't filter on UNINDEXED columns efficiently)

        sql += " ORDER BY rank LIMIT 100"

        var results = try await executeQuery(sql, params: params)

        // Post-filter in Swift
        if \!filters.markingTypes.isEmpty {
            results = results.filter { filters.markingTypes.contains($0.markingType) }
        }

        if filters.favoritesOnly {
            results = results.filter { $0.isFavorite }
        }

        if let minConfidence = filters.minConfidence {
            results = results.filter { ($0.confidence ?? 1.0) >= minConfidence }
        }

        return SearchResults(quotes: Array(results.prefix(50)), books: [], query: query)
    }
}
```

