## Task
Implement a production-grade search service using **SQLite FTS5** for blazing-fast full-text search. This is the gold standard for mobile search - the same technology powers millions of apps.

## Why SQLite FTS5?

| Approach | Speed (1000 docs) | Fuzzy | Phrase | Persist | Memory |
|----------|-------------------|-------|--------|---------|--------|
| String.contains | ~500ms | ❌ | ❌ | ✅ | Low |
| In-memory tokens | ~50ms | Slow | ❌ | ❌ | High |
| **SQLite FTS5** | **<5ms** | ✅ | ✅ | ✅ | Low |
| Core Spotlight | ~20ms | ❌ | ✅ | ✅ | Low |

FTS5 is:
- **Native C code** - No Swift overhead
- **B-tree optimized** - O(log n) lookups
- **BM25 ranking** - Industry-standard relevance
- **Persistent** - No rebuild on launch
- **Battle-tested** - Used by iOS Mail, Notes, Safari

## Implementation Details

### Database Setup (alongside SwiftData)
```swift
import SQLite3

actor SearchDatabase {
    private var db: OpaquePointer?
    private let dbPath: URL

    init() throws {
        // Store in app's documents directory
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        dbPath = docs.appendingPathComponent("search_index.sqlite")

        try openDatabase()
        try createFTSTables()
    }

    private func openDatabase() throws {
        guard sqlite3_open(dbPath.path, &db) == SQLITE_OK else {
            throw SearchError.databaseOpenFailed
        }
    }

    private func createFTSTables() throws {
        // FTS5 virtual table for quotes
        let createQuotesSQL = """
            CREATE VIRTUAL TABLE IF NOT EXISTS quotes_fts USING fts5(
                quote_id UNINDEXED,
                book_id UNINDEXED,
                text,
                margin_note,
                book_title,
                book_author,
                tokenize='porter unicode61'
            );
        """

        // FTS5 virtual table for books
        let createBooksSQL = """
            CREATE VIRTUAL TABLE IF NOT EXISTS books_fts USING fts5(
                book_id UNINDEXED,
                title,
                author,
                subtitle,
                tokenize='porter unicode61'
            );
        """

        try execute(createQuotesSQL)
        try execute(createBooksSQL)
    }
}
```

### Key FTS5 Features Used

#### 1. Porter Stemming Tokenizer
```sql
tokenize='porter unicode61'
```
- "running" matches "run", "runs", "ran"
- "happiness" matches "happy", "happier"
- Handles Unicode properly

#### 2. Prefix Matching (Instant Search)
```sql
SELECT * FROM quotes_fts WHERE quotes_fts MATCH 'happi*'
-- Finds: happiness, happy, happier, happily
```

#### 3. Phrase Matching
```sql
SELECT * FROM quotes_fts WHERE quotes_fts MATCH '"to be or not to be"'
-- Finds exact phrase only
```

#### 4. BM25 Relevance Ranking
```sql
SELECT *, bm25(quotes_fts) as rank 
FROM quotes_fts 
WHERE quotes_fts MATCH ?
ORDER BY rank
-- Best matches first, considering term frequency and document length
```

#### 5. Fuzzy Matching with Trigrams
```sql
-- For typo tolerance, use trigram auxiliary function
CREATE VIRTUAL TABLE IF NOT EXISTS quotes_trigram USING fts5(
    quote_id UNINDEXED,
    text,
    tokenize='trigram'
);
-- 'hapiness' will match 'happiness' via shared trigrams
```

### SearchService Implementation
```swift
@MainActor
@Observable
final class SearchService {
    private let searchDB: SearchDatabase
    private var currentTask: Task<Void, Never>?

    private(set) var results: SearchResults = .empty
    private(set) var isSearching = false

    init() throws {
        self.searchDB = try SearchDatabase()
    }

    /// Debounced search with instant prefix matching
    func search(_ query: String, scope: SearchScope) {
        currentTask?.cancel()

        guard !query.trimmingCharacters(in: .whitespaces).isEmpty else {
            results = .empty
            return
        }

        currentTask = Task {
            // Short debounce for responsiveness
            try? await Task.sleep(for: .milliseconds(150))
            guard !Task.isCancelled else { return }

            isSearching = true
            defer { isSearching = false }

            do {
                let searchResults = try await searchDB.search(
                    query: query,
                    scope: scope
                )

                guard !Task.isCancelled else { return }
                results = searchResults
            } catch {
                results = .empty
            }
        }
    }
}
```

### FTS5 Search Query Builder
```swift
extension SearchDatabase {
    func search(query: String, scope: SearchScope) async throws -> SearchResults {
        // Build FTS5 query with prefix matching for partial words
        let ftsQuery = buildFTSQuery(query)

        var quotes: [SearchQuoteResult] = []
        var books: [SearchBookResult] = []

        if scope == .all || scope == .quotes {
            quotes = try await searchQuotes(ftsQuery)
        }

        if scope == .all || scope == .books {
            books = try await searchBooks(ftsQuery)
        }

        return SearchResults(quotes: quotes, books: books, query: query)
    }

    /// Build FTS5 query with prefix matching
    private func buildFTSQuery(_ input: String) -> String {
        let terms = input
            .lowercased()
            .components(separatedBy: .whitespaces)
            .filter { !/bin/bash.isEmpty }

        // Add prefix operator to last term for instant search
        // "swift program" → "swift program*"
        if terms.count == 1 {
            return "\(terms[0])*"
        } else {
            let allButLast = terms.dropLast().joined(separator: " ")
            let last = terms.last!
            return "\(allButLast) \(last)*"
        }
    }

    private func searchQuotes(_ ftsQuery: String) async throws -> [SearchQuoteResult] {
        let sql = """
            SELECT 
                quote_id,
                book_id,
                snippet(quotes_fts, 2, '<mark>', '</mark>', '...', 32) as snippet,
                bm25(quotes_fts, 0.0, 0.0, 1.0, 0.5, 0.5, 0.3) as rank
            FROM quotes_fts 
            WHERE quotes_fts MATCH ?
            ORDER BY rank
            LIMIT 50
        """

        // snippet() extracts context with <mark> tags around matches
        // bm25() weights: text=1.0, margin_note=0.5, book_title=0.5, author=0.3

        return try executeQuery(sql, params: [ftsQuery])
    }
}
```

### Snippet Extraction (Built-in Highlighting)
```swift
// FTS5 snippet() function returns pre-highlighted text:
// "...the quick <mark>brown</mark> <mark>fox</mark> jumps over..."

struct SearchQuoteResult {
    let quoteId: UUID
    let bookId: UUID
    let snippet: String  // Pre-highlighted by FTS5
    let rank: Double

    /// Convert FTS5 <mark> tags to AttributedString
    var highlightedSnippet: AttributedString {
        var result = AttributedString(snippet)

        // Replace <mark>...</mark> with yellow highlight
        while let startRange = result.range(of: "<mark>"),
              let endRange = result.range(of: "</mark>") {

            // Remove tags, apply highlight
            result.removeSubrange(endRange)
            result.removeSubrange(startRange)

            let highlightStart = startRange.lowerBound
            let highlightEnd = result.index(afterCharacter: endRange.lowerBound)
            result[highlightStart..<highlightEnd].backgroundColor = .yellow.opacity(0.4)
            result[highlightStart..<highlightEnd].font = .body.bold()
        }

        return result
    }
}
```

### Index Maintenance
```swift
extension SearchDatabase {
    /// Call when quote is added or updated
    func indexQuote(_ quote: Quote, book: Book) async throws {
        // Delete old entry if exists
        try await execute(
            "DELETE FROM quotes_fts WHERE quote_id = ?",
            params: [quote.id.uuidString]
        )

        // Insert new entry
        try await execute("""
            INSERT INTO quotes_fts (quote_id, book_id, text, margin_note, book_title, book_author)
            VALUES (?, ?, ?, ?, ?, ?)
        """, params: [
            quote.id.uuidString,
            book.id.uuidString,
            quote.text,
            quote.marginNote ?? "",
            book.title,
            book.author
        ])
    }

    /// Call when quote is deleted
    func removeQuote(id: UUID) async throws {
        try await execute(
            "DELETE FROM quotes_fts WHERE quote_id = ?",
            params: [id.uuidString]
        )
    }

    /// Rebuild entire index (background, on first launch after update)
    func rebuildIndex(quotes: [Quote], books: [Book]) async throws {
        try await execute("DELETE FROM quotes_fts")
        try await execute("DELETE FROM books_fts")

        for book in books {
            try await indexBook(book)
            for quote in book.quotes {
                try await indexQuote(quote, book: book)
            }
        }
    }
}
```

### Fuzzy Search Fallback
```swift
extension SearchDatabase {
    /// If FTS5 returns no results, try fuzzy trigram search
    func fuzzySearch(_ query: String) async throws -> [SearchQuoteResult] {
        // Trigram table catches typos that porter stemmer misses
        let sql = """
            SELECT quote_id, book_id, 
                   snippet(quotes_trigram, 1, '<mark>', '</mark>', '...', 32),
                   bm25(quotes_trigram) as rank
            FROM quotes_trigram
            WHERE quotes_trigram MATCH ?
            ORDER BY rank
            LIMIT 20
        """

        // Convert query to trigram-friendly format
        let trigramQuery = query.map { String(/bin/bash) }.joined(separator: " ")
        return try executeQuery(sql, params: [trigramQuery])
    }
}
```

