## Task
Implement BatchProcessingService for parallel processing of captured pages with progress tracking.

## Why This Matters
Processing 20 pages sequentially takes too long. Parallel processing with proper rate limiting speeds up the workflow while respecting API limits.

## Implementation Details

### BatchProcessingService
```swift
actor BatchProcessingService {
    private let geminiService: GeminiService
    private let maxConcurrent = 3    // Respect rate limits

    @Published var progress: BatchProgress

    struct BatchProgress {
        let total: Int
        var completed: Int
        var failed: Int
        var currentlyProcessing: Set<UUID>

        var percentComplete: Double {
            Double(completed + failed) / Double(total)
        }
    }

    func processSession(_ session: CaptureSession, markings: [MarkingDefinition]) async throws {
        progress = BatchProgress(total: session.captures.count)

        await withTaskGroup(of: ProcessingResult.self) { group in
            var activeCount = 0
            var captureIterator = session.captures.makeIterator()

            // Seed initial batch
            while activeCount < maxConcurrent, let capture = captureIterator.next() {
                group.addTask {
                    await self.processCapture(capture, markings: markings)
                }
                activeCount += 1
            }

            // Process results, add new tasks
            for await result in group {
                handleResult(result)

                if let nextCapture = captureIterator.next() {
                    group.addTask {
                        await self.processCapture(nextCapture, markings: markings)
                    }
                }
            }
        }
    }

    private func processCapture(_ capture: PageCapture, markings: [MarkingDefinition]) async -> ProcessingResult
}
```

