## Task
Implement DuplicateDetector with Levenshtein distance for fuzzy quote matching.

## Why This Matters
Users may capture the same passage multiple times from different sessions. Duplicate detection prevents cluttered libraries and wasted storage.

## Implementation Details

### DuplicateDetector
```swift
actor DuplicateDetector {
    private let modelContext: ModelContext
    private let similarityThreshold: Double = 0.85

    struct DuplicateResult {
        let existingQuote: Quote
        let similarityScore: Double
        let isExactMatch: Bool
    }

    func checkForDuplicates(text: String, inBook book: Book? = nil) async -> [DuplicateResult] {
        let quotes = await fetchQuotes(book: book)

        return quotes.compactMap { quote in
            let similarity = levenshteinSimilarity(text, quote.text)
            guard similarity >= similarityThreshold else { return nil }

            return DuplicateResult(
                existingQuote: quote,
                similarityScore: similarity,
                isExactMatch: similarity >= 0.99
            )
        }
        .sorted { \$0.similarityScore > \$1.similarityScore }
    }

    private func levenshteinSimilarity(_ s1: String, _ s2: String) -> Double {
        let distance = levenshteinDistance(s1, s2)
        let maxLength = max(s1.count, s2.count)
        guard maxLength > 0 else { return 1.0 }
        return 1.0 - (Double(distance) / Double(maxLength))
    }
}
```

### Levenshtein Distance Algorithm
```swift
func levenshteinDistance(_ s1: String, _ s2: String) -> Int {
    let (a, b) = (Array(s1), Array(s2))
    var dp = Array(0...b.count)

    for i in 1...a.count {
        var prev = dp[0]
        dp[0] = i

        for j in 1...b.count {
            let temp = dp[j]
            if a[i-1] == b[j-1] {
                dp[j] = prev
            } else {
                dp[j] = min(prev, dp[j], dp[j-1]) + 1
            }
            prev = temp
        }
    }
    return dp[b.count]
}
```

