## Task
Create a comprehensive test logging infrastructure that provides detailed, structured logs for debugging test failures.

## Why This Matters
When tests fail in CI or on another developer's machine, you need:
- **Step-by-step trace** of what happened
- **Timestamps** for performance analysis
- **Context** about test state at each point
- **File output** for post-mortem analysis

## Implementation Details

### TestLogger
```swift
import Foundation
import os.log

/// Thread-safe test logger with structured output
/// Conforms to Sendable for safe use across actor boundaries
final class TestLogger: Sendable {
    enum Level: String, Sendable {
        case trace = "⚪️ TRACE"
        case debug = "🔵 DEBUG"
        case info = "🟢 INFO"
        case step = "👉 STEP"
        case warning = "🟡 WARN"
        case error = "🔴 ERROR"
        case success = "✅ PASS"
        case failure = "❌ FAIL"
    }

    struct LogEntry: Sendable, Codable {
        let timestamp: Date
        let level: String
        let testName: String
        let message: String
        let file: String
        let line: Int
        let context: [String: String]

        var formatted: String {
            let time = Self.formatter.string(from: timestamp)
            let location = "\(file.split(separator: "/").last ?? ""):\(line)"
            return "[\(time)] [\(level)] [\(testName)] \(message) (\(location))"
        }

        private static let formatter: ISO8601DateFormatter = {
            let f = ISO8601DateFormatter()
            f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
            return f
        }()
    }

    private let testName: String
    private let logFileURL: URL?
    private let osLog: OSLog
    private let entries: LockedState<[LogEntry]>

    init(testName: String, writeToFile: Bool = true) {
        self.testName = testName
        self.osLog = OSLog(subsystem: "com.bookquotes.tests", category: testName)
        self.entries = LockedState([])

        if writeToFile {
            let logsDir = FileManager.default.temporaryDirectory
                .appendingPathComponent("BookQuotesTestLogs", isDirectory: true)
            try? FileManager.default.createDirectory(at: logsDir, withIntermediateDirectories: true)

            let timestamp = Date().timeIntervalSince1970
            self.logFileURL = logsDir.appendingPathComponent("\(testName)_\(Int(timestamp)).log")
        } else {
            self.logFileURL = nil
        }
    }

    // MARK: - Logging Methods

    func trace(
        _ message: String,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        log(.trace, message, context: context, file: file, line: line)
    }

    func debug(
        _ message: String,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        log(.debug, message, context: context, file: file, line: line)
    }

    func info(
        _ message: String,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        log(.info, message, context: context, file: file, line: line)
    }

    func step(
        _ stepNumber: Int,
        _ message: String,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        log(.step, "Step \(stepNumber): \(message)", context: context, file: file, line: line)
    }

    func warning(
        _ message: String,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        log(.warning, message, context: context, file: file, line: line)
    }

    func error(
        _ message: String,
        error: Error? = nil,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        var ctx = context
        if let error = error {
            ctx["error"] = String(describing: error)
        }
        log(.error, message, context: ctx, file: file, line: line)
    }

    func success(
        _ message: String,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        log(.success, message, context: context, file: file, line: line)
    }

    func failure(
        _ message: String,
        context: [String: String] = [:],
        file: String = #file,
        line: Int = #line
    ) {
        log(.failure, message, context: context, file: file, line: line)
    }

    // MARK: - Core Logging

    private func log(
        _ level: Level,
        _ message: String,
        context: [String: String],
        file: String,
        line: Int
    ) {
        let entry = LogEntry(
            timestamp: Date(),
            level: level.rawValue,
            testName: testName,
            message: message,
            file: file,
            line: line,
            context: context
        )

        // Store entry
        entries.withLock { $0.append(entry) }

        // Console output
        os_log("%{public}@", log: osLog, type: osLogType(for: level), entry.formatted)

        // File output
        appendToFile(entry)
    }

    private func osLogType(for level: Level) -> OSLogType {
        switch level {
        case .trace, .debug: return .debug
        case .info, .step, .success: return .info
        case .warning: return .default
        case .error, .failure: return .error
        }
    }

    private func appendToFile(_ entry: LogEntry) {
        guard let url = logFileURL else { return }
        let line = entry.formatted + "\n"

        if let data = line.data(using: .utf8) {
            if FileManager.default.fileExists(atPath: url.path) {
                if let handle = try? FileHandle(forWritingTo: url) {
                    handle.seekToEndOfFile()
                    handle.write(data)
                    handle.closeFile()
                }
            } else {
                try? data.write(to: url)
            }
        }
    }

    // MARK: - Summary

    func summary() -> String {
        let allEntries = entries.withLock { $0 }
        let errorCount = allEntries.filter { $0.level.contains("ERROR") || $0.level.contains("FAIL") }.count
        let stepCount = allEntries.filter { $0.level.contains("STEP") }.count

        return """
        ══════════════════════════════════════════════════════════
        TEST: \(testName)
        STEPS: \(stepCount)
        ERRORS: \(errorCount)
        LOG FILE: \(logFileURL?.path ?? "none")
        ══════════════════════════════════════════════════════════
        """
    }

    /// Export all entries as JSON for CI analysis
    func exportJSON() -> Data? {
        let allEntries = entries.withLock { $0 }
        return try? JSONEncoder().encode(allEntries)
    }
}

// MARK: - Thread-Safe State Container

/// Sendable wrapper for mutable state
final class LockedState<T>: @unchecked Sendable {
    private var value: T
    private let lock = NSLock()

    init(_ value: T) {
        self.value = value
    }

    func withLock<R>(_ body: (inout T) throws -> R) rethrows -> R {
        lock.lock()
        defer { lock.unlock() }
        return try body(&value)
    }
}
```

