### HighlightedText Component
```swift
struct HighlightedText: View {
    let text: String
    let query: String
    var maxLength: Int = 200
    var highlightColor: Color = .yellow.opacity(0.4)

    var body: some View {
        Text(buildAttributedString())
    }

    private func buildAttributedString() -> AttributedString {
        // 1. Find first match location
        let lowerText = text.lowercased()
        let lowerQuery = query.lowercased()
        let queryTerms = lowerQuery.split(separator: " ").map(String.init)

        // 2. Find the best match position (where most terms appear close together)
        var bestStart = 0
        if let firstTermRange = lowerText.range(of: queryTerms.first ?? "") {
            let matchPosition = lowerText.distance(from: lowerText.startIndex, to: firstTermRange.lowerBound)
            bestStart = max(0, matchPosition - 30) // 30 chars before match
        }

        // 3. Extract context window
        let startIndex = text.index(text.startIndex, offsetBy: min(bestStart, text.count))
        let endOffset = min(bestStart + maxLength, text.count)
        let endIndex = text.index(text.startIndex, offsetBy: endOffset)

        var snippet = String(text[startIndex..<endIndex])

        // Add ellipsis
        if bestStart > 0 { snippet = "..." + snippet }
        if endOffset < text.count { snippet = snippet + "..." }

        // 4. Build attributed string with highlights
        var attributed = AttributedString(snippet)

        for term in queryTerms where term.count >= 2 {
            var searchStart = attributed.startIndex
            while let range = attributed[searchStart...].range(of: term, options: .caseInsensitive) {
                attributed[range].backgroundColor = highlightColor
                attributed[range].font = .body.bold()
                searchStart = range.upperBound
            }
        }

        return attributed
    }
}
