### ExportService
```swift
actor ExportService {
    enum ExportFormat: String, CaseIterable, Identifiable {
        case markdown = "Markdown"
        case plainText = "Plain Text"
        case json = "JSON"
        case notion = "Notion"
        case obsidian = "Obsidian"

        var id: String { rawValue }
        var fileExtension: String {
            switch self {
            case .markdown, .obsidian: return "md"
            case .plainText: return "txt"
            case .json: return "json"
            case .notion: return "" // API, no file
            }
        }
    }

    func export(
        quotes: [Quote],
        format: ExportFormat,
        options: ExportOptions
    ) async throws -> ExportResult {
        switch format {
        case .markdown:
            return try await MarkdownFormatter().format(quotes, options: options)
        case .plainText:
            return try await PlainTextFormatter().format(quotes, options: options)
        case .json:
            return try await JSONFormatter().format(quotes, options: options)
        case .notion:
            return try await NotionExporter().export(quotes, options: options)
        case .obsidian:
            return try await ObsidianFormatter().format(quotes, options: options)
        }
    }
}

struct ExportOptions {
    var includeMetadata: Bool = true
    var groupByBook: Bool = true
    var includePageNumbers: Bool = true
    var includeMarginNotes: Bool = true
    var dateFormat: String = "yyyy-MM-dd"
}

enum ExportResult {
    case file(URL, filename: String)
    case apiSuccess(message: String)
    case apiError(message: String)
}
