## Task
Implement MarkdownFormatter for human-readable quote export with proper formatting.

## Why This Matters
Markdown is universally supported and human-readable. It's the default export format for most users.

## Implementation Details

### MarkdownFormatter
```swift
struct MarkdownFormatter: QuoteFormatter {
    func format(_ quotes: [Quote], options: ExportOptions) async throws -> ExportResult {
        var output = ""

        if options.groupByBook {
            let grouped = Dictionary(grouping: quotes, by: { \$0.book })

            for (book, bookQuotes) in grouped.sorted(by: { \$0.key?.title ?? "" < \$1.key?.title ?? "" }) {
                if let book = book {
                    output += "# \(book.title)\n"
                    output += "*by \(book.author)*\n\n"
                }

                for quote in bookQuotes {
                    output += formatQuote(quote, options: options)
                    output += "\n---\n\n"
                }
            }
        } else {
            for quote in quotes {
                output += formatQuote(quote, options: options)
                output += "\n---\n\n"
            }
        }

        let filename = "BookQuotes_Export_\(Date().formatted(.iso8601)).md"
        let url = try saveToTempFile(output, filename: filename)
        return .file(url, filename: filename)
    }

    private func formatQuote(_ quote: Quote, options: ExportOptions) -> String {
        var md = ""

        // Quote text as blockquote
        md += "> \(quote.text)\n\n"

        // Attribution
        if options.includeMetadata {
            var attribution = ""
            if let page = quote.pageNumber, options.includePageNumbers {
                attribution += "p. \(page)"
            }
            if let marking = quote.customMarkingDefinition?.name ?? quote.markingType.displayName {
                attribution += " • \(marking)"
            }
            if !attribution.isEmpty {
                md += "*\(attribution)*\n"
            }
        }

        // Margin note
        if options.includeMarginNotes, let note = quote.marginNote {
            md += "\n**Note:** \(note)\n"
        }

        return md
    }
}
