## Task
Implement ObsidianFormatter with YAML frontmatter for vault-ready markdown files.

## Why This Matters
Obsidian users expect markdown with YAML frontmatter containing metadata. Proper formatting enables seamless integration with their knowledge base.

## Implementation Details

### ObsidianFormatter
```swift
struct ObsidianFormatter: QuoteFormatter {
    func format(_ quotes: [Quote], options: ExportOptions) async throws -> ExportResult {
        var files: [(String, String)] = []

        let grouped = Dictionary(grouping: quotes, by: { \$0.book })

        for (book, bookQuotes) in grouped {
            guard let book = book else { continue }

            var content = ""

            // YAML frontmatter
            content += "---\n"
            content += "title: \"\(book.title)\"\n"
            content += "author: \"\(book.author)\"\n"
            if let isbn = book.isbn {
                content += "isbn: \"\(isbn)\"\n"
            }
            content += "type: book-quotes\n"
            content += "quote_count: \(bookQuotes.count)\n"
            content += "date_exported: \(Date().ISO8601Format())\n"
            content += "tags:\n"
            content += "  - book-quotes\n"
            content += "  - reading\n"
            content += "---\n\n"

            // Title
            content += "# \(book.title)\n"
            content += "*by \(book.author)*\n\n"

            // Quotes
            for quote in bookQuotes.sorted(by: { (\$0.pageNumber ?? 0) < (\$1.pageNumber ?? 0) }) {
                content += "## \n\n"  // H2 divider
                content += "> \(quote.text)\n\n"

                if let page = quote.pageNumber {
                    content += "Page \(page)"
                }
                if let marking = quote.customMarkingDefinition?.name {
                    content += " • \(marking)"
                }
                content += "\n\n"

                if let note = quote.marginNote {
                    content += "**Note:** \(note)\n\n"
                }
            }

            let filename = sanitizeFilename("\(book.title) - Quotes.md")
            files.append((filename, content))
        }

        // Create zip if multiple files, otherwise single file
        return try await packageFiles(files)
    }
}
